22	  backgroundImage,
23	  cta = "Play now",
24	  onClick,
25	  index = 0,
26	  disabled = false,
27	}: GameTileProps) {
28	  const reduce = useReducedMotionSafe();
29	
30	  // The photo mounts only client-side, post-hydration. In the server-rendered
31	  // markup even loading="lazy" images fetch immediately (Chrome's lazy
32	  // threshold spans kilopixels), and 18 tile JPGs would crowd the bandwidth
33	  // the first paint needs. Until then the tile shows its scrim + text.
34	  const [showImg, setShowImg] = useState(false);
35	  useEffect(() => setShowImg(true), []);
36	
37	  return (
38	    <motion.button
39	      className={`gtile${disabled ? " is-disabled" : ""}`}
40	      onClick={disabled ? undefined : onClick}
41	      disabled={disabled}
42	      aria-disabled={disabled}
43	      initial={reduce ? false : { opacity: 0, y: 16 }}
44	      whileInView={{ opacity: 1, y: 0 }}
45	      viewport={{ once: true, amount: 0.25 }}
46	      transition={{ duration: 0.38, ease: [0.22, 1, 0.36, 1], delay: Math.min(index * 0.04, 0.24) }}
47	      whileHover={reduce || disabled ? undefined : { y: -4 }}
48	      whileTap={reduce || disabled ? undefined : { scale: 0.98, y: 0 }}
49	    >
50	      {showImg && (
51	        <img
52	          className="gtile-img"
53	          src={backgroundImage.replace(/^url\(['"]?/, "").replace(/['"]?\)$/, "")}
54	          alt=""
55	          loading="lazy"
56	          decoding="async"
57	          draggable={false}
58	        />
59	      )}
60	      <div className="gtile-scrim" />
61	      <div className="gtile-body">
